  str_n31_1_name_desc = "/",
  str_n31_2_name_desc = "Schwartz memiliki pertemuan dengan utusan Northland, Jakine, yang datang untuk mengisi Crystal of Eternal Memory dengan air dari Lake Mirror. Anda dan Mia menemukan adegan ini secara kebetulan.",
  str_n31_3_name_desc = "Kalian berdua menemukan bahwa kalian mungkin telah memasuki sejarah yang direkam oleh Crystal of Eternal Memory, tetapi situasinya tampaknya tidak stabil...",
  str_n31_4_name_desc = "Anda dan Mia bukan satu-satunya yang ditarik ke dalam Crystal of Eternal Memory. Di sudut jauh Lumopolis, dua individu lainnya juga bertemu dengan Eclipsites.",
  str_n31_5_name_desc = "Anda membuntuti penjaga ke gerbang Lumopolis dan terkejut menemukan sekelompok Eclipsites bersembunyi di tengah barang yang masuk.",
  str_n31_6_name_desc = "/",
  str_n31_7_name_desc = "Schwartz bertanya Mia untuk bergabung dalam duel di depan semua orang. Tidak ingin hanya menampilkan pertunjukan, Mia meminta lawannya untuk tidak menahan diri.",
  str_n31_8_name_desc = "Penampilan Mia yang luar biasa dalam duel membuatnya mendapat sorakan. Sepertinya duel akan berlangsung cukup lama.",
  str_n31_9_name_desc = "Selama duel, Mia tanpa sengaja menghancurkan kotak kayu di sekelilingnya. Sedikit yang dia tahu bahwa ada kejutan tersembunyi yang tersembunyi di dalam ...",
  str_n31_10_name_desc = "Saat alun-alun tengah berubah menjadi kekacauan, orang-orang melarikan diri ke segala arah. Di tengah keributan itu, Sharona melangkah maju, menawarkan bantuan Jakine dalam menemukan Anda dan Mia.",
  str_n31_11_name_desc = "Lebih banyak Eclipsites muncul dari sudut Lumopolis, sementara sekelompok penjaga mendekat dengan tertib. Namun, menjadi jelas bahwa mereka bukanlah bala bantuan.",
  str_n31_12_name_desc = "/",
  str_n31_13_name_desc = "Mengikuti Schwartz, Anda dan Mia tiba di tempat persembunyian pemberontak, di mana Anda bertemu dengan tentara pemberontak yang bersembunyi di bayang-bayang, seperti yang diharapkan.",
  str_n31_14_name_desc = "Bersandar ke tembok, para prajurit pemberontak bersiap untuk bertempur, dan tampaknya mereka telah memanggil sekutu yang tangguh juga...",
  str_n31_15_name_desc = "/",
  str_n31_16_name_desc = "Schwartz melemparkan pandangan penuh arti pada Joshua, penuh dengan kata-kata yang tak terucapkan. Tapi makan malam dengan cahaya lilin mereka tiba-tiba terganggu...",
  str_n31_1_name_desc_long = "Mengenakan setelan sewaan yang mahal, Anda bersiap untuk menghadiri pesta perayaan Schwartz Hari Keluarga di Lumopolis. Saat Anda akan pergi, Northland Messenger yang diharapkan gagal tiba, tetapi sebaliknya, Anda berpapasan dengannya Mia. Dia tampak sangat berbeda, dan dengan rasa takut, dia mengungkapkan keinginannya untuk menemukan keluarganya.",
  str_n31_2_name_desc_long = "Utusan Northland, Jakine, mengisi kembali Crystal of Eternal Memory dengan air dari Lake Mirror. Setelah mendengar bahwa orang yang pernah mengaktifkan Crystal of Eternal Memory tidak lagi berada di dunia ini, Jakine memutuskan untuk menemukan cara lain untuk membantu Schwartz memasuki ranah Crystal sekali lagi.",
  str_n31_3_name_desc_long = "Anda dan Mia dibawa ke dunia Crystal of Eternal Memory, tapi kalian semua hilang. Saat Anda menjelajah, Anda menyadari bahwa Anda telah tersandung ke dalam Schwartz Perayaan Hari Keluarga sejak dua belas tahun lalu. Anehnya, orang-orang di sekitar Anda alamat Mia sebagai Putri Veronica dengan penuh hormat.",
  str_n31_4_name_desc_long = "Terlepas dari keberatan Jakine, Caleb, menyadari dia telah memasuki Crystal of Eternal Memory, membuat keputusan untuk melanjutkan sendiri.",
  str_n31_5_name_desc_long = "Caleb bertemu saudara perempuannya di rumah Schwartz, tetapi dia tidak mengenalinya setelah dua belas tahun. Sedangkan kamu dan Mia bantu penjaga di gerbang Lumopolis melawan sekelompok Eclipsites yang tersembunyi di antara kargo, tempat Anda diperkenalkan dengan Kapten Ksatria Mime Kartima.",
  str_n31_6_name_desc_long = "Keraguan Mia sirna saat dia menatap ibunya, Joshua, dan saudara perempuannya Carleen. Mimpi yang jelas dalam benaknya bukan lagi khayalannya sendiri. Mia akhirnya menerima kebenaran bahwa dia pernah menjadi Putri Veronica.",
  str_n31_7_name_desc_long = "Seorang wanita mabuk mengolok-olok keterampilan ramalan Jakine dan menemukan Anda dan Mia untuk Jakine selama parade kereta. Namun, karena jaraknya, Anda tidak dapat melihat Jakine. Setelah pawai, Schwartz bersikeras bahwa Mia bergabunglah dengan ritual duel, dan saat itulah Anda melihat tekad Mia yang tak tergoyahkan untuk pertama kalinya.",
  str_n31_8_name_desc_long = "Didorong oleh niatnya untuk mencuri Crystal of Eternal Memory dari dunia, Caleb dengan cepat melumpuhkan para penjaga di mansion Schwartz. Sementara itu, Jakine mendapati dirinya terpaksa percaya bahwa wanita yang tampaknya tidak mencolok di hadapannya itu memang ibunya sendiri.",
  str_n31_9_name_desc_long = "Di dalam Kristal Memori Abadi, Schwartz akhirnya bertemu denganmu. Dia menyalahkanmu karena membiarkan Mia mengambil risiko berpartisipasi dalam duel. Namun, seperti yang Anda lihat Mia di ambang memenangkan duel, Anda tidak mengerti mengapa Schwartz masih begitu khawatir.",
  str_n31_10_name_desc_long = "Schwartz ingin melarikan diri dari daerah yang dipenuhi Eclipsite Mia dan kamu, tetapi dia dibatasi oleh Schwartz dari dalam Crystal of Eternal Memory. Meskipun hanya ada jarak dua belas tahun antara kedua Schwartz, mereka tidak lagi memiliki kemiripan satu sama lain.",
  str_n31_11_name_desc_long = "Jakine akhirnya bertemu kembali denganmu, tetapi situasi di depan tampak suram. Eclipsites terus bermunculan, dan faksi pemberontak lainnya berdiri di depan Anda. Akhirnya menjadi jelas mengapa Schwartz telah bersikeras untuk menjaga Mia dan Anda jauh dari Schwartz dari dunia ini.",
  str_n31_12_name_desc_long = "Meski ditikam, Schwartz dari dalam Crystal of Eternal Memory berhasil menangkis para pemberontak dengan bantuan massa. Terbukti bahwa Mime Kartima adalah dalang pemberontakan. Ketika Schwartz keinginan untuk melindungi Mia dari menghidupkan kembali sejarah itu, tekadnya untuk mengungkap kebenaran tetap tak tergoyahkan.",
  str_n31_13_name_desc_long = "Setelah menemukan tempat persembunyian para pemberontak, Schwartz dalam Crystal of Eternal Memory menginstruksikan Mia untuk mencapai kemenangan dengan segala cara yang diperlukan, sikap yang tidak dapat Anda dukung. Sedangkan yang lainnya Schwartz mengungkapkan harapannya bahwa Anda dapat menemukan jalan alternatif.",
  str_n31_14_name_desc_long = "Mime Kartima memanggil naga terbang untuk membantu, tapi Schwartz sangat melawan naga sendirian. Pada akhirnya, Schwartz mengakhiri pemberontakan, seperti yang diharapkan.",
  str_n31_15_name_desc_long = "Dengan periode paling berbahaya di belakang mereka, Schwartz akhirnya mengungkap sisi lembutnya yang jarang terlihat. Jakine menggunakan sihir untuk memulihkan Schwartz untuk penampilan mudanya, memberinya kesempatan untuk mengucapkan selamat tinggal yang pantas kepada Joshua, yang tidak pernah bisa dia lepaskan dari hatinya.",
  str_n31_16_name_desc_long = "Tanpa peringatan, dunia Crystal of Eternal Memory tiba-tiba runtuh menjadi sebuah pulau kecil, dengan bayangan mengejar Anda tanpa henti. Saat bel tengah malam berbunyi, pertanyaan mendesak tetap ada: apakah semua orang akan lolos dari Crystal of Eternal Memory tanpa cedera?",
  str_n31_h1_name = "H1 - Sembuh",
  str_n31_h2_name = "H2 - Wali",
  str_n31_h3_name = "H3 - Mengepung",
  str_n31_h4_name = "H4 - Pengorbanan",
