  str_n31_h10_name = "EX4 - Bunuh",
  str_n31_h11_name = "EX5 - Waylay",
  str_n31_h12_name = "EX6 - Pelopor",
  str_n31_h1_name_desc = "Dalam perjalanan, banyak rintangan seperti duri. Tapi dengan tekad yang tak tergoyahkan, kita bisa dengan cepat menyembuhkan luka di sepanjang jalan.",
  str_n31_h2_name_desc = "Serangan normal tidak akan berhasil. Saatnya untuk melepaskan keterampilan kuat Anda.",
  str_n31_h3_name_desc = "Jika Anda tidak dapat membuat kemajuan dari depan, mungkin ada baiknya mencoba pendekatan menyamping, bahkan jika itu berarti mengambil jalan memutar yang panjang...",
  str_n31_h4_name_desc = "Panas terik mengintensifkan pertempuran, menghadirkan risiko yang lebih besar bagi semua orang yang terlibat.",
  str_n31_h5_name_desc = "Tetap waspada terhadap jebakan, tetapi juga ingat untuk memanfaatkan setiap peluang yang mungkin mereka hadirkan.",
  str_n31_h6_name_desc = "Serangan musuh datang seperti gelombang tanpa henti. Berusaha keras untuk melemahkan dan mengalahkannya sebelum serangan berikutnya.",
  str_n31_h7_name_desc = "Terkadang, bukan Bos itu sendiri yang terbukti mematikan, melainkan antek-antek yang bersembunyi di dekatnya.",
  str_n31_h8_name_desc = "Bertarung di medan berbahaya ini bukanlah hal yang mudah. Mungkin Anda bisa membalikkan keadaan dan mengeksploitasi kerentanan musuh untuk keuntungan Anda.",
  str_n31_h9_name_desc = "Kekuatan musuh meningkat pada tahap pertempuran yang menentukan. Kalahkan mereka dengan cepat untuk mengamankan kemenangan.",
  str_n31_h10_name_desc = "Raih keuntungan dengan menghabisi musuh dengan cepat tepat setelah mereka tampaknya membalikkan keadaan untuk Anda.",
  str_n31_h11_name_desc = "Anda harus mencegah bala bantuan musuh yang tak ada habisnya untuk bergabung dalam pertempuran.",
  str_n31_h12_name_desc = "Kuat dan cepat, lawan tampaknya tak terkalahkan. Hanya dengan tekad Anda dapat bertahan hidup.",
  str_n31_blackbox_title = "Pengiriman Genting",
  str_n31_blackbox_intro = "Gerhana menjadi lebih umum di Benua Astra, menimbulkan ancaman yang semakin besar terhadap rute pengiriman. Saat Colossi muncul kembali, Caelestites dan rekan mereka menjadi lebih proaktif. Faksi tertentu mengenali kemampuan terbang dan manuver jarak jauh yang luar biasa dari Colossus, mempercayakan pengiriman khusus dan berisiko kepada mereka.",
  str_n31_activity_blackbox_intro_title = "Info Gameplay Pengiriman Genting",
